WAKEFERN_-_APPT_-_01_Extract_Second_Tabl.inputs:
@if(
  equals(outputs('WAKEFERN_-_APPT_-_01_Has_Second_Table'), true),
  concat(
    '<table',
    first(
      split(
        first(
          skip(
            split(coalesce(outputs('WAKEFERN_-_APPT_-_01_Email_HTML_Body'), ''), '<table'),
            2
          )
        ),
        '</table>'
      )
    ),
    '</table>'
  ),
  ''
)

equals:
@or(
  and(
    not(contains(coalesce(first(triggerOutputs()?['body/value'])?['subject'], ''), 'RE:')),
    not(contains(coalesce(first(triggerOutputs()?['body/value'])?['subject'], ''), 'FW:')),
    or(
      contains(coalesce(first(triggerOutputs()?['body/value'])?['subject'], ''), 'Wakefern GROCERY - OM Action Needed'),
      contains(coalesce(first(triggerOutputs()?['body/value'])?['subject'], ''), 'Wakefern HABA - OM Action Needed')
    )
  ),
  and(
    or(
      startsWith(coalesce(first(triggerOutputs()?['body/value'])?['subject'], ''), 'RE:'),
      startsWith(coalesce(first(triggerOutputs()?['body/value'])?['subject'], ''), 'FW:')
    ),
    contains(toLower(coalesce(first(triggerOutputs()?['body/value'])?['from'], '')), 'mark.kielczynski@wakefern.com')
  )
)
